import { useCallback, useEffect, useState } from "react";
import { Alert } from "react-native";

import { addEntry, patchEntry } from "@/modules/entry";
import { getTag, getTags, MAX_TAGS_PER_ENTRY } from "@/services/db/tags";
import { getCachedPlace, useLocation } from "@/services/location";
import type { Attachment, Entry, Tag } from "@/shared/types";
import { getInitialWhen } from "@/shared/utils/dates";
import { reportError } from "@/shared/utils/devLog";
import { canSaveDraft, fromDraft } from "../utils/DraftTransform";

/** What `save` did, so the screen can navigate accordingly. */
export type SaveOutcome = "created" | "updated" | "aborted";

interface ComposeMedia {
  images: string[];
  audios: string[];
  attachments: Attachment[];
  isRecording: boolean;
}

interface ComposeDraftOptions {
  existing: Entry | undefined;
  media: ComposeMedia;
  initialDate?: number;
  /** Pre-attaches this tag to a new entry, e.g. when composing from a tag's timeline. */
  initialTagId?: string;
}

/**
 * Scalar draft state (text, timestamp, location) plus the pipeline that
 * persists the whole draft — media included — into a stored entry.
 */
export function useComposeDraft({
  existing,
  media,
  initialDate,
  initialTagId,
}: ComposeDraftOptions) {
  const [text, setText] = useState(() => existing?.text ?? "");
  const [tags, setTags] = useState<Tag[]>(() => existing?.tags ?? []);
  const [when, setWhen] = useState(() => getInitialWhen(existing?.createdAt, initialDate));
  const [saving, setSaving] = useState(false);
  const location = useLocation(existing ? existing.location : getCachedPlace());

  useEffect(() => {
    if (!existing) return;
    let active = true;
    getTags()
      .then((availableTags) => {
        if (!active) return;
        const byId = new Map(availableTags.map((tag) => [tag.id, tag]));
        setTags((current) =>
          current.flatMap((tag) => {
            const updated = byId.get(tag.id);
            return updated ? [updated] : [];
          })
        );
      })
      .catch((error) => reportError("compose:refreshTags", error));
    return () => {
      active = false;
    };
  }, [existing]);

  useEffect(() => {
    if (existing || !initialTagId) return;
    let active = true;
    getTag(initialTagId)
      .then((tag) => {
        if (!active || !tag) return;
        setTags((current) =>
          current.length >= MAX_TAGS_PER_ENTRY || current.some((item) => item.id === tag.id)
            ? current
            : [tag, ...current]
        );
      })
      .catch((error) => reportError("compose:initialTag", error));
    return () => {
      active = false;
    };
  }, [existing, initialTagId]);

  const canSave =
    canSaveDraft({
      text,
      images: media.images,
      audios: media.audios,
      attachments: media.attachments,
    }) &&
    !media.isRecording &&
    !saving;

  const save = useCallback(async (): Promise<SaveOutcome> => {
    if (!canSave) return "aborted";

    setSaving(true);
    try {
      const input = await fromDraft({
        text,
        images: media.images,
        audios: media.audios,
        attachments: media.attachments,
        tags,
        createdAt: when,
        location: location.on && location.place ? location.place : null,
      });
      if (!input) return "aborted";

      if (existing) {
        await patchEntry(existing.id, input);
        return "updated";
      }

      await addEntry(input);
      return "created";
    } catch (error) {
      reportError("compose:save", error);
      Alert.alert("Couldn't save", "Something went wrong. Try again.");
      return "aborted";
    } finally {
      setSaving(false);
    }
  }, [
    canSave,
    text,
    media.images,
    media.audios,
    media.attachments,
    tags,
    when,
    location.on,
    location.place,
    existing,
  ]);

  /** Discard edits and restore the entry's stored draft fields. */
  const reset = useCallback(() => {
    setText(existing?.text ?? "");
    setTags(existing?.tags ?? []);
    setWhen(getInitialWhen(existing?.createdAt, initialDate));
    location.reset();
  }, [existing, initialDate, location.reset]);

  return { text, setText, tags, setTags, when, setWhen, location, canSave, save, reset };
}
import type { Attachment, EntryLocation, Tag } from "@/shared/types";

/** Cap on photos attached to a single entry. */
export const MAX_IMAGES = 10;

/** Cap on generic documents (PDFs, videos, spreadsheets, …) attached to a single entry. */
export const MAX_ATTACHMENTS = 10;

export interface Draft {
  text?: string;
  images?: string[];
  audios?: string[];
  attachments?: Attachment[];
  tags?: Tag[];
  createdAt?: number;
  /** `null` clears an attached location when editing. */
  location?: EntryLocation | null;
}
import { persistAttachment, persistMedia } from "@/services/media";
import type { NewEntryInput } from "@/shared/types";
import type { Draft } from "../types";

export function canSaveDraft(draft: Draft): boolean {
  return Boolean(
    draft.text?.trim() || draft.images?.length || draft.audios?.length || draft.attachments?.length
  );
}

/** Turn write-screen draft into a database entry, persisting media when needed. */
export async function fromDraft(draft: Draft): Promise<NewEntryInput | null> {
  const text = draft.text?.trim() || null;
  const createdAt = draft.createdAt;
  const location = draft.location;

  const images = draft.images?.length
    ? await Promise.all(draft.images.map((imageUri) => persistMedia(imageUri, "jpg")))
    : [];

  const audios = draft.audios?.length
    ? await Promise.all(draft.audios.map((audioUri) => persistMedia(audioUri, "m4a")))
    : [];

  // Attachments are persisted when saving, keeping drafts ephemeral.
  const attachments = draft.attachments?.length
    ? await Promise.all(draft.attachments.map(persistAttachment))
    : [];

  if (text || images.length || audios.length || attachments.length) {
    return {
      text,
      images,
      audios,
      attachments,
      tagIds: draft.tags?.map((tag) => tag.id),
      createdAt,
      location,
    };
  }

  return null;
}
