import * as ImagePicker from "expo-image-picker";
import { useCallback, useEffect, useState } from "react";

import { analytics } from "@/config/analytics";
import { useRecording } from "@/services/audio";
import { downscaleImage, pickDocuments } from "@/services/media";
import type { Attachment, Entry } from "@/shared/types";
import { MAX_ATTACHMENTS, MAX_IMAGES } from "../types";

/**
 * Photos, voice notes, and kept documents attached to a compose draft, plus
 * the side effects that capture them (picker permissions, recorder lifecycle).
 * Isolated here so the screen's render loop stays free of media concerns.
 */
export function useMediaAttachments(existing?: Entry) {
  const [images, setImages] = useState<string[]>(() => existing?.images ?? []);
  const [audios, setAudios] = useState<string[]>(() => existing?.audios ?? []);
  const [attachments, setAttachments] = useState<Attachment[]>(() => existing?.attachments ?? []);

  const {
    isRecording,
    durationMs: recordingDurationMs,
    liveLevels: recordingLevels,
    recordedUri,
    toggle,
    cancel,
    clear,
  } = useRecording();

  // Commit a finished take into the attachments list so the next recording
  // starts from a clean slate.
  useEffect(() => {
    if (!recordedUri || isRecording) return;
    setAudios((prev) => (prev.includes(recordedUri) ? prev : [...prev, recordedUri]));
    clear();
  }, [recordedUri, isRecording, clear]);

  const pickImage = useCallback(async () => {
    if (images.length >= MAX_IMAGES) return;

    const { granted } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!granted) return;

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: "images",
      // Full quality here — downscaleImage performs the only re-encode.
      quality: 1,
      allowsMultipleSelection: true,
      selectionLimit: MAX_IMAGES - images.length,
    });
    if (!result.canceled) {
      // Shrink before state so the preview and the durable copy share one small file.
      const downscaled = await Promise.all(
        result.assets.map((asset) => downscaleImage(asset.uri, asset))
      );
      setImages((prev) => [...prev, ...downscaled]);
      analytics.capture("photo_attached", { photo_count: downscaled.length });
    }
  }, [images.length]);

  const pickAttachments = useCallback(async () => {
    if (attachments.length >= MAX_ATTACHMENTS) return;

    const picked = await pickDocuments(MAX_ATTACHMENTS - attachments.length);
    if (picked.length > 0) {
      setAttachments((prev) => [...prev, ...picked]);
      analytics.capture("file_attached", { file_count: picked.length });
    }
  }, [attachments.length]);

  const removeImage = useCallback((index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAudio = useCallback((index: number) => {
    setAudios((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  }, []);

  /** Discard edits and restore the entry's stored media. */
  const reset = useCallback(() => {
    // Stop the mic and drop any in-progress or finished-but-unsaved take.
    void cancel();
    setImages(existing?.images ?? []);
    setAudios(existing?.audios ?? []);
    setAttachments(existing?.attachments ?? []);
    clear();
  }, [existing, cancel, clear]);

  return {
    images,
    audios,
    attachments,
    isRecording,
    recordingDurationMs,
    recordingLevels,
    pickImage,
    pickAttachments,
    removeImage,
    removeAudio,
    removeAttachment,
    toggleRecording: toggle,
    reset,
  };
}

import { Directory, File, Paths } from "expo-file-system";

import { waitForExportGate, waitForImportGate } from "@/services/backup/utils";
import { reportError } from "@/shared/utils/devLog";

/** The app's single durable media directory; the database stores bare filenames relative to it. */
export function mediaDirectory(): Directory {
  return new Directory(Paths.document, "media");
}

/** Resolves a stored media filename (e.g. "uuid.jpg") to its live file URI for display and playback. */
export function mediaFileUri(filename: string): string {
  return new File(mediaDirectory(), filename).uri;
}

/** Generates a collision-free filename for durable media storage. */
function createMediaFilename(ext: string): string {
  const cleanExt = ext.replace(/^\./, "").toLowerCase() || "bin";
  const uuid =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  return `${uuid}.${cleanExt}`;
}

/**
 * Copies a picked or recorded file into the durable media directory and returns
 * its stored filename. Cache and picker URIs are ephemeral, so only durable
 * copies may be referenced by an entry. A source already inside the media
 * directory passes through unchanged — re-editing an entry must not duplicate
 * its files.
 */
export async function persistMedia(sourceUri: string, ext: string): Promise<string> {
  await waitForImportGate();
  const dir = mediaDirectory();
  dir.create({ idempotent: true, intermediates: true });

  const dirPrefix = dir.uri.endsWith("/") ? dir.uri : `${dir.uri}/`;
  if (sourceUri.startsWith(dirPrefix)) {
    return sourceUri.slice(dirPrefix.length);
  }

  const filename = createMediaFilename(ext);
  await new File(sourceUri).copy(new File(dir, filename));
  return filename;
}

/** Deletes stored media files by filename. Missing files are ignored. */
export async function deleteMediaFiles(filenames: string[]): Promise<void> {
  if (!filenames.length) return;
  await waitForExportGate();
  await waitForImportGate();

  const dir = mediaDirectory();
  await Promise.all(
    filenames.map(async (filename) => {
      try {
        const file = new File(dir, filename);
        if (file.exists) file.delete();
      } catch (error) {
        reportError("media:deleteFiles", error);
      }
    })
  );
}
import * as DocumentPicker from "expo-document-picker";
import { Alert } from "react-native";
import { open } from "react-native-file-viewer-turbo";

import type { Attachment } from "@/shared/types";
import { logDevWarning } from "@/shared/utils/devLog";
import { persistMedia } from "./storage";

/** Derives a safe extension from a filename or mime type; `bin` as the last resort. */
function fileExtension(name: string, mime?: string): string {
  const ext = name.includes(".") ? (name.split(".").pop() ?? "") : "";
  if (ext && /^[a-zA-Z0-9]{1,8}$/.test(ext)) return ext.toLowerCase();
  const mimeExt = mime?.split("/").pop();
  if (mimeExt && /^[a-zA-Z0-9]{1,8}$/.test(mimeExt)) return mimeExt.toLowerCase();
  return "bin";
}

/**
 * Opens the system document picker for any file type and copies each selection
 * into cache. URIs remain ephemeral until the draft is saved.
 */
export async function pickDocuments(maxCount: number): Promise<Attachment[]> {
  if (maxCount <= 0) return [];

  const result = await DocumentPicker.getDocumentAsync({
    type: "*/*",
    multiple: true,
    copyToCacheDirectory: true,
  });
  if (result.canceled) return [];

  const picked = result.assets.slice(0, maxCount);
  const attachments: Attachment[] = [];

  for (const asset of picked) {
    attachments.push({
      uri: asset.uri,
      name: asset.name || "File",
      mime: asset.mimeType,
      size: asset.size,
    });
  }

  return attachments;
}

