import type { Attachment, EntryLocation, Tag } from "@/shared/types";

/** Unsaved compose content. Media fields hold live file URIs. */
export interface DraftSnapshot {
  text: string;
  images: string[];
  audios: string[];
  attachments: Attachment[];
  tags: Tag[];
  createdAt: number;
  location: EntryLocation | null;
}

const DRAFT_FORMAT_VERSION = 1;

/** Bounds a restored list so a damaged draft file cannot flood the compose screen. */
const MAX_DRAFT_ITEMS = 50;

/** Draft slots are named "new" or by entry id; nothing that could escape the drafts directory. */
export function isDraftKey(key: string): boolean {
  return /^[A-Za-z0-9-]{1,64}$/.test(key);
}

/**
 * A stored file reference: a path relative to the document directory, either
 * entry media ("media/<file>") or a draft-owned copy ("drafts/<key>/<file>").
 */
export function isDraftFileRef(ref: string): boolean {
  return /^(media|drafts\/[A-Za-z0-9-]{1,64})\/[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(ref);
}

/** Stable comparison key: two drafts with the same signature store the same content. */
export function draftSignature(draft: DraftSnapshot): string {
  return JSON.stringify([
    draft.text,
    draft.images,
    draft.audios,
    draft.attachments.map((attachment) => [attachment.uri, attachment.name]),
    draft.tags.map((tag) => tag.id),
    draft.createdAt,
    draft.location
      ? [draft.location.latitude, draft.location.longitude, draft.location.name ?? null]
      : null,
  ]);
}

/** Serializes a draft whose media fields already hold file refs. */
export function serializeDraftSnapshot(draft: DraftSnapshot): string {
  return JSON.stringify({ version: DRAFT_FORMAT_VERSION, ...draft });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseRefs(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter((ref): ref is string => typeof ref === "string" && isDraftFileRef(ref))
    .slice(0, MAX_DRAFT_ITEMS);
}

function parseAttachments(value: unknown): Attachment[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(isRecord)
    .filter((item) => typeof item.uri === "string" && isDraftFileRef(item.uri))
    .slice(0, MAX_DRAFT_ITEMS)
    .map((item) => ({
      uri: item.uri as string,
      name: typeof item.name === "string" && item.name ? item.name : "File",
      mime: typeof item.mime === "string" ? item.mime : undefined,
      size: typeof item.size === "number" ? item.size : undefined,
    }));
}

function parseTags(value: unknown): Tag[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(isRecord)
    .filter(
      (item) =>
        typeof item.id === "string" &&
        typeof item.name === "string" &&
        typeof item.colorId === "string"
    )
    .slice(0, MAX_DRAFT_ITEMS)
    .map((item) => ({
      id: item.id as string,
      name: item.name as string,
      colorId: item.colorId as Tag["colorId"],
    }));
}

function parseLocation(value: unknown): EntryLocation | null {
  if (!isRecord(value)) return null;
  const { latitude, longitude, name } = value;
  if (typeof latitude !== "number" || !Number.isFinite(latitude)) return null;
  if (typeof longitude !== "number" || !Number.isFinite(longitude)) return null;
  return typeof name === "string" ? { latitude, longitude, name } : { latitude, longitude };
}

/**
 * Parses a stored draft whose media fields hold file refs. Unknown versions
 * and malformed files yield `null`; malformed fields are dropped individually.
 * Tag colors are refreshed from the database on restore.
 */
export function parseDraftSnapshot(json: string): DraftSnapshot | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch {
    return null;
  }
  if (!isRecord(parsed) || parsed.version !== DRAFT_FORMAT_VERSION) return null;
  if (typeof parsed.createdAt !== "number" || !Number.isFinite(parsed.createdAt)) return null;

  return {
    text: typeof parsed.text === "string" ? parsed.text : "",
    images: parseRefs(parsed.images),
    audios: parseRefs(parsed.audios),
    attachments: parseAttachments(parsed.attachments),
    tags: parseTags(parsed.tags),
    createdAt: parsed.createdAt,
    location: parseLocation(parsed.location),
  };
}

import { Directory, File, Paths } from "expo-file-system";

import type { Attachment } from "@/shared/types";
import {
  type DraftSnapshot,
  isDraftFileRef,
  isDraftKey,
  parseDraftSnapshot,
  serializeDraftSnapshot,
} from "./snapshot";

/** Draft slot for an entry that has not been saved yet; edits use the entry id. */
export const NEW_ENTRY_DRAFT = "new";

const DRAFT_FILE = "draft.json";
// Written first and renamed over DRAFT_FILE, so a crash mid-write keeps the previous draft.
const PENDING_FILE = "draft.pending.json";
const MAX_DRAFT_BYTES = 4 * 1024 * 1024;

// Picker, recorder, and image-manipulator URIs point into the OS cache, which may be
// purged after the app dies, so a draft keeps its own copy of each such file. This
// remembers which copy belongs to which source so autosave copies a file only once.
const copiesByKey = new Map<string, Map<string, string>>();

// One operation at a time: a slow write must not land after the discard that followed it.
let queue: Promise<unknown> = Promise.resolve();

function enqueue<T>(task: () => Promise<T>): Promise<T> {
  const run = queue.then(task);
  queue = run.catch(() => undefined);
  return run;
}

function draftsDirectory(): Directory {
  return new Directory(Paths.document, "drafts");
}

function draftDirectory(key: string): Directory {
  if (!isDraftKey(key)) throw new Error("Invalid draft key.");
  return new Directory(draftsDirectory(), key);
}

function documentPrefix(): string {
  const uri = Paths.document.uri;
  return uri.endsWith("/") ? uri : `${uri}/`;
}

function createDraftFilename(sourceUri: string): string {
  const basename = sourceUri.split("?")[0].split("/").pop() ?? "";
  const ext = basename.includes(".") ? (basename.split(".").pop() ?? "") : "";
  const cleanExt = /^[a-zA-Z0-9]{1,8}$/.test(ext) ? ext.toLowerCase() : "bin";
  const uuid =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  return `${uuid}.${cleanExt}`;
}

/** Returns the stored ref for a live URI, copying files from outside the document directory. */
async function toFileRef(options: {
  key: string;
  dir: Directory;
  uri: string;
  copies: Map<string, string>;
}): Promise<string> {
  const { key, dir, uri, copies } = options;
  const prefix = documentPrefix();
  if (uri.startsWith(prefix)) {
    const ref = decodeURI(uri.slice(prefix.length));
    if (isDraftFileRef(ref)) return ref;
  }

  const copied = copies.get(uri);
  if (copied && new File(dir, copied).exists) return `drafts/${key}/${copied}`;

  const filename = createDraftFilename(uri);
  await new File(uri).copy(new File(dir, filename));
  copies.set(uri, filename);
  return `drafts/${key}/${filename}`;
}

/** Resolves a stored ref to a live URI, or `null` when its file is gone. */
function fromFileRef(ref: string): string | null {
  const file = new File(Paths.document, ref);
  return file.exists ? file.uri : null;
}

/** Deletes draft-owned copies the latest draft no longer references. */
function pruneCopies(options: { key: string; dir: Directory; refs: Set<string> }): void {
  const { key, dir, refs } = options;
  for (const item of dir.list()) {
    if (!(item instanceof File) || item.name === DRAFT_FILE || item.name === PENDING_FILE) continue;
    if (!refs.has(`drafts/${key}/${item.name}`)) item.delete();
  }
  const copies = copiesByKey.get(key);
  if (!copies) return;
  for (const [source, filename] of copies) {
    if (!refs.has(`drafts/${key}/${filename}`)) copies.delete(source);
  }
}

/** Writes the draft for `key`, replacing any earlier one. */
export function writeDraft(key: string, draft: DraftSnapshot): Promise<void> {
  return enqueue(async () => {
    const dir = draftDirectory(key);
    dir.create({ idempotent: true, intermediates: true });
    const copies = copiesByKey.get(key) ?? new Map<string, string>();
    copiesByKey.set(key, copies);

    const ref = (uri: string) => toFileRef({ key, dir, uri, copies });
    const images = await Promise.all(draft.images.map(ref));
    const audios = await Promise.all(draft.audios.map(ref));
    const attachments = await Promise.all(
      draft.attachments.map(
        async (attachment): Promise<Attachment> => ({
          ...attachment,
          uri: await ref(attachment.uri),
        })
      )
    );

    const pending = new File(dir, PENDING_FILE);
    pending.write(serializeDraftSnapshot({ ...draft, images, audios, attachments }));
    pending.moveSync(new File(dir, DRAFT_FILE), { overwrite: true });

    pruneCopies({
      key,
      dir,
      refs: new Set([...images, ...audios, ...attachments.map((attachment) => attachment.uri)]),
    });
  });
}

/**
 * Reads the draft for `key` with media resolved to live URIs. Files that have
 * since disappeared are dropped; an unreadable draft reads as none.
 */
export function loadDraft(key: string): Promise<DraftSnapshot | null> {
  return enqueue(async () => {
    const dir = draftDirectory(key);
    if (!dir.exists) return null;

    for (const name of [DRAFT_FILE, PENDING_FILE]) {
      const file = new File(dir, name);
      if (!file.exists || file.size > MAX_DRAFT_BYTES) continue;
      const stored = parseDraftSnapshot(await file.text());
      if (!stored) continue;

      const resolve = (refs: string[]) =>
        refs.flatMap((ref) => {
          const uri = fromFileRef(ref);
          return uri ? [uri] : [];
        });
      return {
        ...stored,
        images: resolve(stored.images),
        audios: resolve(stored.audios),
        attachments: stored.attachments.flatMap((attachment) => {
          const uri = fromFileRef(attachment.uri);
          return uri ? [{ ...attachment, uri }] : [];
        }),
      };
    }
    return null;
  });
}

/** Removes the draft for `key` and every file only it owned. */
export function discardDraft(key: string): Promise<void> {
  return enqueue(async () => {
    copiesByKey.delete(key);
    const dir = draftDirectory(key);
    if (dir.exists) dir.delete();
  });
}

/** Removes every stored draft, e.g. when all entries are deleted. */
export function discardAllDrafts(): Promise<void> {
  return enqueue(async () => {
    copiesByKey.clear();
    const dir = draftsDirectory();
    if (dir.exists) dir.delete();
  });
}

